INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('erkennt_sensible_daten_im_text_a', 'cli', 'ru', 'Обнаруживает конфиденциальные данные в тексте.
        
