INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('erwirbt_exklusiven_file_lock_gibt_false_zurueck_w', 'cli', 'ja', '排他的ファイルロックを取得します。すでにロックされている場合は False を返します。

