INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('help_handler_zeigt_hilfe_texte_aus_txt_dateien', 'cli', 'ja', 'ヘルプ ハンドラー - .txt ファイルからのヘルプ テキストを表示します。
