INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('merged_remote_backup_in_lokale_db_mit_timestamp_ba', 'cli', 'es', 'Copia de seguridad remota fusionada en una base de datos local con estrategia basada en marca de tiempo.

