    --to=NAME             Specific partner
    --zone=N              Force zone (1-4)
    --fallback-local, --fal  Fall back to local AI (Ollama) when offline', 0, 'waterfall_swarm', '2026-03-06 19:53:38', '2026-03-06 19:53:38');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('partner_handler_partner_verwaltung', 'cli', 'es', 'Controlador de socios - Gestión de socios
