INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_aliase_zu_skills_strukturen_agents_workfl', 'cli', 'de', 'Prueft Aliase zu skills-Strukturen (agents, workflows, experts).

        Ermoeglicht:
          --help agent/ati      -> skills/_agents/ati/ATI.md
          --help workflow/bugfix -> skills/_workflows/bugfix-protokoll.md
          --help expert/steuer   -> skills/_experts/steuer/STEUER.md

        Returns:
            Dateiinhalt oder None wenn nicht gefunden.', 0, 'auto_detected', '2026-02-02T03:35:38.883979', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_aliase_zu_skills_strukturen_agents_workfl', 'cli', 'en', 'Checks aliases for skills structures (agents, workflows, experts).

        Enables:
          --help agent/ati      -> skills/_agents/ati/ATI.md
          --help workflow/bugfix -> skills/_workflows/bugfix-protokoll.md
          --help expert/steuer   -> skills/_experts/steuer/STEUER.md

        Returns:
            File content or None if not found.', 0, 'waterfall_swarm', '2026-03-06 19:53:38', '2026-03-06 19:53:38');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_aliase_zu_skills_strukturen_agents_workfl', 'cli', 'es', 'Comprueba los alias de las estructuras de habilidades (agentes, flujos de trabajo, expertos).

        Permite:
          --ayuda agente/ati -> habilidades/_agents/ati/ATI.md
          --ayuda a flujo de trabajo/corrección de errores -> habilidades/_workflows/bugfix-protokoll.md
          --ayuda experto/steuer -> habilidades/_experts/steuer/STEUER.md

        Devoluciones:
            Contenido del archivo o Ninguno si no se encuentra.', 0, 'google_auto', '2026-05-17T06:03:58.337154', '2026-05-17T06:03:58.337154');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_aliase_zu_skills_strukturen_agents_workfl', 'cli', 'ja', 'スキル構造 (エージェント、ワークフロー、エキスパート) のエイリアスをチェックします。

        有効にするもの:
          --ヘルプ エージェント/ati -> スキル/_agents/ati/ATI.md
          --help ワークフロー/バグ修正 -> スキル/_workflows/bugfix-protokoll.md
          --help エキスパート/steuer -> スキル/_experts/steuer/STEUER.md

        戻り値:
            ファイルの内容、または見つからない場合は「なし」。', 0, 'google_auto', '2026-05-17T06:33:13.916677', '2026-05-17T06:33:13.916677');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_aliase_zu_skills_strukturen_agents_workfl', 'cli', 'ru', 'Проверяет псевдонимы структур навыков (агенты, рабочие процессы, эксперты).

        Позволяет:
          --help агент/ati -> навыки/_агенты/ati/ATI.md
          --help рабочий процесс/исправление ошибок -> навыки/_workflows/bugfix-protokoll.md
          --help expert/steuer -> навыки/_experts/steuer/STEUER.md

        Возврат:
            Содержимое файла или «Нет», если не найдено.', 0, 'google_auto', '2026-05-17T06:24:37.729914', '2026-05-17T06:24:37.729914');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('prueft_aliase_zu_skills_strukturen_agents_workfl', 'cli', 'zh', '检查技能结构的别名（代理、工作流程、专家）。

        启用：
          --帮助代理/ati -> 技能/_agents/ati/ATI.md
          --帮助工作流/bugfix -> 技能/_workflows/bugfix-protokoll.md
          --帮助专家/steuer -> 技能/_experts/steuer/STEUER.md

        返回：
            文件内容或无（如果未找到）。', 0, 'google_auto', '2026-05-17T06:44:24.774895', '2026-05-17T06:44:24.774895');
