INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('smarthomehandler_smart_home_integration_fritzbo', 'cli', 'zh', 'SmartHomeHandler - 智能家居集成 (FritzBox)
=======================================================

操作：
