INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('bach_gui_sync_service_synchronisiert_txt_dateien', 'gui', 'ru', 'Служба синхронизации GUI BACH — синхронизирует файлы TXT с базой данных.

