INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_name_provider_category_m', 'gui', 'de', 'SELECT
                name, provider, category, monthly_cost, status, source_table,
                COUNT(*) as duplicates,
                GROUP_CONCAT(id) as duplicate_ids
            FROM v_subscriptions
            WHERE status = ''active''
            GROUP BY LOWER(name), LOWER(COALESCE(provider, ''''))
            ORDER BY monthly_cost DESC', 0, 'auto_detected', '2026-02-02T03:38:26.254252', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_name_provider_category_m', 'gui', 'en', 'SELECT
                name, provider, category, monthly_cost, status, source_table,
                COUNT(*) as duplicates,
                GROUP_CONCAT(id) as duplicate_ids
            FROM v_subscriptions
            WHERE status = ''active''
            GROUP BY LOWER(name), LOWER(COALESCE(provider, ''''))
            ORDER BY monthly_cost DESC', 0, 'waterfall_swarm', '2026-03-06 19:52:15', '2026-03-06 19:52:15');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_name_provider_category_m', 'gui', 'es', 'SELECCIONAR
                nombre, proveedor, categoría, costo_mensual, estado, tabla_fuente,
                CONTAR(*) como duplicados,
                GROUP_CONCAT(id) como duplicados_ids
            DE v_suscripciones
            DONDE estado = ''activo''
            GRUPO POR INFERIOR(nombre), INFERIOR(FUSIONAR(proveedor, ''''))
            ORDENAR POR costo_mensual DESC', 0, 'google_auto', '2026-05-17T06:00:34.349852', '2026-05-17T06:00:34.349852');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_name_provider_category_m', 'gui', 'ja', '選択
                名前、プロバイダー、カテゴリ、monthly_cost、status、source_table、
                COUNT(*) は重複として、
                GROUP_CONCAT(id) を重複 ID として
            FROM v_subscriptions
            WHERE ステータス = ''アクティブ''
            GROUP BY LOWER(name), LOWER(COALESCE(provider, ''''))
            ORDER BY month_cost DESC', 0, 'google_auto', '2026-05-17T06:33:13.916677', '2026-05-17T06:33:13.916677');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('select_name_provider_category_m', 'gui', 'ru', 'ВЫБРАТЬ
