INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_bestehende_projekte_auf_bach_strukturvorg', 'skills', 'de', 'Migriert bestehende Projekte auf BACH-Strukturvorgaben.
    
    Workflow:
    1. Analyse: Vergleich mit Ziel-Template
    2. Backup: Snapshot vor Migration
    3. Migration: Struktur anpassen
    4. Validierung: Ergebnis prüfen', 0, 'auto_detected', '2026-02-02T03:38:35.221245', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_bestehende_projekte_auf_bach_strukturvorg', 'skills', 'en', 'Migrates existing projects to BACH structure standards.
    
    Workflow:
    1. Analysis: Comparison with target template
    2. Backup: Snapshot before migration
    3. Migration: Adjust structure
    4. Validation: Verify result', 0, 'waterfall_swarm', '2026-03-06 19:53:09', '2026-03-06 19:53:09');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_bestehende_projekte_auf_bach_strukturvorg', 'skills', 'es', 'Migra proyectos existentes a estándares de estructura BACH.
    
    Flujo de trabajo:
    1. Análisis: comparación con la plantilla objetivo
    2. Copia de seguridad: instantánea antes de la migración
    3. Migración: ajustar la estructura
    4. Validación: verificar resultado', 0, 'google_auto', '2026-05-17T06:14:23.208353', '2026-05-17T06:14:23.208353');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_bestehende_projekte_auf_bach_strukturvorg', 'skills', 'ja', '既存のプロジェクトを BACH 構造標準に移行します。
    
    ワークフロー:
    1. 分析：対象テンプレートとの比較
    2. バックアップ: 移行前のスナップショット
    3. 移行: 構造の調整
    4. 検証: 結果を検証する', 0, 'google_auto', '2026-05-17T06:33:13.916677', '2026-05-17T06:33:13.916677');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_bestehende_projekte_auf_bach_strukturvorg', 'skills', 'ru', 'Переносит существующие проекты на структурные стандарты BACH.
    
    Рабочий процесс:
    1. Анализ: сравнение с целевым шаблоном
    2. Резервное копирование: снимок перед миграцией.
    3. Миграция: корректировка структуры
    4. Валидация: проверьте результат.', 0, 'google_auto', '2026-05-17T06:24:37.729914', '2026-05-17T06:24:37.729914');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_bestehende_projekte_auf_bach_strukturvorg', 'skills', 'zh', '将现有项目迁移到 BACH 结构标准。
    
    工作流程：
    1. 分析：与目标模板的比较
    2. 备份：迁移前的快照
    3、迁移：调整结构
    4. 验证：验证结果', 0, 'google_auto', '2026-05-17T06:40:24.434869', '2026-05-17T06:40:24.434869');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_ein_bestehendes_projekt_auf_bach_struktur', 'skills', 'de', 'Migriert ein bestehendes Projekt auf BACH-Strukturvorgaben.
        
        Args:
            project_path: Pfad zum bestehenden Projekt
            target_template: Ziel-Template
            modules: Module zum Hinzufügen
            policies: Anzuwendende Policies
            dry_run: Nur prüfen, nicht ändern
            
        Returns:
            Dict mit Migration-Ergebnis', 0, 'auto_detected', '2026-02-02T03:38:35.218879', NULL);
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_ein_bestehendes_projekt_auf_bach_struktur', 'skills', 'en', 'Migrates an existing project to BACH structure standards.
        
        Args:
            project_path: Path to the existing project
            target_template: Target template
            modules: Modules to add
            policies: Policies to apply
            dry_run: Only check, do not modify
            
        Returns:
            Dict with migration result', 0, 'waterfall_swarm', '2026-03-06 19:53:09', '2026-03-06 19:53:09');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_ein_bestehendes_projekt_auf_bach_struktur', 'skills', 'es', 'Migra un proyecto existente a los estándares de estructura BACH.
        
        Argumentos:
            project_path: ruta al proyecto existente
            target_template: plantilla de destino
            módulos: Módulos para agregar
            políticas: Políticas a aplicar
            dry_run: solo verificar, no modificar
            
        Devoluciones:
            Dict con resultado de migración', 0, 'google_auto', '2026-05-17T06:14:23.208353', '2026-05-17T06:14:23.208353');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_ein_bestehendes_projekt_auf_bach_struktur', 'skills', 'ja', '既存のプロジェクトを BACH 構造標準に移行します。
        
        引数:
            project_path: 既存のプロジェクトへのパス
            target_template: ターゲット テンプレート
            modules: 追加するモジュール
            ポリシー: 適用するポリシー
            dry_run: チェックのみを行い、変更しないでください
            
        戻り値:
            移行結果を含む辞書', 0, 'google_auto', '2026-05-17T06:33:13.916677', '2026-05-17T06:33:13.916677');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_ein_bestehendes_projekt_auf_bach_struktur', 'skills', 'ru', 'Переносит существующий проект на структурные стандарты BACH.
        
        Аргументы:
            project_path: Путь к существующему проекту.
            target_template: целевой шаблон
            модули: Модули для добавления
            политики: политики, которые необходимо применить
            Dry_run: Только проверять, не изменять
            
        Возврат:
            Dict с результатом миграции', 0, 'google_auto', '2026-05-17T06:24:37.729914', '2026-05-17T06:24:37.729914');
INSERT OR REPLACE INTO languages_translations (key, namespace, language, value, is_verified, source, created_at, updated_at) VALUES ('migriert_ein_bestehendes_projekt_auf_bach_struktur', 'skills', 'zh', '将现有项目迁移到 BACH 结构标准。
        
